function validate([difficulty, profit, worker]) {
  if (difficulty.length < 1 || difficulty.length > 10000) return 'There are 1 to 10000 jobs.';
  if (profit.length !== difficulty.length) return 'difficulty and profit must have the same length.';
  if (worker.length < 1 || worker.length > 10000) return 'There are 1 to 10000 workers.';
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 100000;
  if (![...difficulty, ...profit, ...worker].every(ok)) return 'Every value is an integer between 1 and 100000.';
  return null;
}

