function maxProfitAssignment(difficulty, profit, worker) {
  const jobs = difficulty.map((level, i) => [level, profit[i]]);
  jobs.sort((a, b) => a[0] - b[0]);
  const workers = [...worker].sort((a, b) => a - b);
  let total = 0;
  let best = 0;
  let j = 0;

  for (const ability of workers) {
    while (j < jobs.length && jobs[j][0] <= ability) {
      best = Math.max(best, jobs[j][1]);
      j++;
    }
    total += best;
  }
  return total;
}

