function maxProfitAssignment(difficulty, profit, worker) {
  // Every worker looks at every job and takes the best one within reach.
  let total = 0;
  for (const ability of worker) {
    let earn = 0;
    for (let i = 0; i < difficulty.length; i++) if (difficulty[i] <= ability && profit[i] > earn) earn = profit[i];
    total += earn;
  }
  return total;
}

