function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 6);
  const m = large ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 6);
  const top = large ? 100000 : 12;
  const value = () => 1 + Math.floor(rand() * top);
  return [Array.from({ length: n }, value), Array.from({ length: n }, value), Array.from({ length: m }, value)];
}
